export interface RedisResource extends ResourceBuilderBase {
    toJSON(): MarshalledHandle;
    primaryEndpoint(): Promise<EndpointReferenceHandle>;
    host(): Promise<EndpointReferenceExpressionHandle>;
    port(): Promise<EndpointReferenceExpressionHandle>;
    passwordParameter: { get: () => ParameterResourcePromise; set: (value: Awaitable<ParameterResource>) => Promise<void> };
    tlsEnabled(): Promise<boolean>;
    connectionStringExpression(): Promise<ReferenceExpression>;
    uriExpression(): Promise<ReferenceExpression>;
    withRedisCommander(options?: WithRedisCommanderOptions): RedisResourcePromise;
    withRedisInsight(options?: WithRedisInsightOptions): RedisResourcePromise;
    withDataVolume(options?: WithDataVolumeOptions): RedisResourcePromise;
    withDataBindMount(source: string, options?: WithDataBindMountOptions): RedisResourcePromise;
    withPersistence(options?: WithPersistenceOptions): RedisResourcePromise;
    withModule(path: string): RedisResourcePromise;
    withPassword(password: Awaitable<ParameterResource>): RedisResourcePromise;
    withHostPort(options?: WithHostPortOptions): RedisResourcePromise;
}

export interface RedisResourcePromise extends PromiseLike<RedisResource> {
    primaryEndpoint(): Promise<EndpointReferenceHandle>;
    host(): Promise<EndpointReferenceExpressionHandle>;
    port(): Promise<EndpointReferenceExpressionHandle>;
    passwordParameter: { get: () => ParameterResourcePromise; set: (value: Awaitable<ParameterResource>) => Promise<void> };
    tlsEnabled(): Promise<boolean>;
    connectionStringExpression(): Promise<ReferenceExpression>;
    uriExpression(): Promise<ReferenceExpression>;
    withRedisCommander(options?: WithRedisCommanderOptions): RedisResourcePromise;
